export const categories = [
  'Travel',
  'Lodging',
  'Meals',
  'Software',
  'Office',
] as const
export type Category = (typeof categories)[number]

/** A saved expense */
export interface Expense {
  id: string
  /** "2026-11-04" */
  date: string
  description: string
  category: Category
  amount: number
}

/** The report covers one month; dates outside it are rejected */
export const period = { from: '2026-11-01', to: '2026-11-30' }
export const periodLabel = 'November 2026'

/** Fixed, rather than the real date, so the server and browser agree */
export const today = '2026-11-17'

export const saved: Expense[] = [
  {
    id: 'exp-1',
    date: '2026-11-03',
    description: 'Train to Lyon',
    category: 'Travel',
    amount: 86.4,
  },
  {
    id: 'exp-2',
    date: '2026-11-03',
    description: 'Hotel Bellecour, 2 nights',
    category: 'Lodging',
    amount: 312,
  },
  {
    id: 'exp-3',
    date: '2026-11-04',
    description: 'Client dinner',
    category: 'Meals',
    amount: 148.5,
  },
  {
    id: 'exp-4',
    date: '2026-11-10',
    description: 'Figma, annual seat',
    category: 'Software',
    amount: 180,
  },
]

import { categories, period, today } from './data'
import type { Category, Expense } from './data'

/** A row being typed: every field is still the raw text from its input */
export interface Draft {
  id: string
  date: string
  description: string
  category: Category | ''
  amount: string
}

export type Field = 'date' | 'description' | 'category' | 'amount'
export const fields: Field[] = ['date', 'description', 'category', 'amount']

export type Errors = Partial<Record<Field, string>>

/** Per-expense limit before it needs a manager's approval */
export const LIMIT = 2_000

/** A new row starts on the date of the row above, which is usually right */
export const emptyDraft = (id: string, after?: Draft): Draft => ({
  id,
  date: after?.date || today,
  description: '',
  category: '',
  amount: '',
})

/** A row nobody typed in: saving skips it instead of failing on it */
export const isBlank = (d: Draft) =>
  !d.description.trim() && !d.category && !d.amount.trim()

/** "1,234.50" or "$12" become numbers; anything else is NaN */
export const parseAmount = (raw: string) =>
  raw.trim() === '' ? NaN : Number(raw.replace(/[$,\s]/g, ''))

export function validate(d: Draft): Errors {
  const errors: Errors = {}
  if (!d.date) errors.date = 'Pick a date'
  else if (d.date < period.from || d.date > period.to)
    errors.date = 'Must be in November 2026'
  else if (d.date > today) errors.date = "Can't be in the future"

  if (!d.description.trim()) errors.description = 'Describe the expense'
  else if (d.description.trim().length > 60)
    errors.description = '60 characters at most'

  if (!d.category) errors.category = 'Pick a category'
  else if (!categories.includes(d.category))
    errors.category = 'Unknown category'

  const amount = parseAmount(d.amount)
  if (d.amount.trim() === '') errors.amount = 'Enter an amount'
  else if (Number.isNaN(amount)) errors.amount = 'Numbers only'
  else if (amount <= 0) errors.amount = 'More than 0'
  else if (/\.\d{3,}$/.test(d.amount.trim())) errors.amount = 'Cents at most'
  else if (amount > LIMIT) errors.amount = `Over the $${LIMIT} limit`
  return errors
}

const signature = (date: string, amount: number, description: string) =>
  `${date}|${amount.toFixed(2)}|${description.trim().toLowerCase()}`

/**
 * Drafts that look like an expense already saved, or like another draft:
 * same date, amount and description. A warning, not an error, since two
 * identical taxi rides on one day can be real.
 */
export function duplicates(drafts: Draft[], existing: Expense[]) {
  const seen = new Set(
    existing.map((e) => signature(e.date, e.amount, e.description)),
  )
  const dupes = new Set<string>()
  for (const d of drafts) {
    const amount = parseAmount(d.amount)
    if (isBlank(d) || Number.isNaN(amount)) continue
    const sig = signature(d.date, amount, d.description)
    if (seen.has(sig)) dupes.add(d.id)
    seen.add(sig)
  }
  return dupes
}

export interface Batch {
  /** Drafts with something typed in */
  filled: Draft[]
  /** Filled drafts that can't be saved yet */
  invalid: Draft[]
  /** Sum of the amounts that parse */
  total: number
}

export function batch(drafts: Draft[]): Batch {
  const filled = drafts.filter((d) => !isBlank(d))
  const invalid = filled.filter((d) => Object.keys(validate(d)).length > 0)
  const total = filled.reduce((sum, d) => {
    const n = parseAmount(d.amount)
    return Number.isNaN(n) ? sum : sum + n
  }, 0)
  return { filled, invalid, total }
}

export const toExpense = (d: Draft, id: string): Expense => ({
  id,
  date: d.date,
  description: d.description.trim(),
  category: d.category as Category,
  amount: parseAmount(d.amount),
})

export const money = (n: number) =>
  n.toLocaleString('en-US', { style: 'currency', currency: 'USD' })

const monthDay = [
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
]

/** "2026-11-04" → "Nov 4", without Date, so time zones can't shift it */
export const formatDate = (iso: string) => {
  const [, m, d] = iso.split('-').map(Number)
  return `${monthDay[m - 1]} ${d}`
}

import { useState } from 'react'
import { CalendarIcon } from 'lucide-react'

import { Button } from '#/components/ui/button'
import { Calendar } from '#/components/ui/calendar'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '#/components/ui/popover'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '#/components/ui/select'
import { cn } from '#/lib/utils'
import { categories, period, today } from './data'
import { formatDate } from './drafts'

/** What a draft cell hands its control: focus hooks and error wiring */
export interface ControlProps {
  'data-draft': string
  'data-field': string
  'aria-invalid': boolean
  'aria-describedby': string | undefined
  disabled: boolean
}

// Dates stay "2026-11-12" strings; the calendar wants local Date objects
const toDate = (iso: string) => {
  const [y, m, d] = iso.split('-').map(Number)
  return new Date(y, m - 1, d)
}
const toIso = (date: Date) =>
  [
    date.getFullYear(),
    String(date.getMonth() + 1).padStart(2, '0'),
    String(date.getDate()).padStart(2, '0'),
  ].join('-')

const first = toDate(period.from)
const last = toDate(today)

export function DateField({
  value,
  label,
  control,
  onChange,
  onClose,
}: {
  value: string
  /** "Date, new row 2" */
  label: string
  control: ControlProps
  onChange: (iso: string) => void
  /** Closing the picker counts as leaving the field */
  onClose: () => void
}) {
  const [open, setOpen] = useState(false)
  const selected = value ? toDate(value) : undefined

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        setOpen(next)
        if (!next) onClose()
      }}
    >
      <PopoverTrigger asChild>
        <Button
          {...control}
          variant="outline"
          size="sm"
          aria-label={`${label}: ${value ? formatDate(value) : 'not set'}`}
          className={cn(
            'h-8 w-28 justify-start px-2 font-normal tabular-nums',
            'aria-invalid:border-destructive aria-invalid:ring-destructive/20',
            !value && 'text-muted-foreground',
          )}
        >
          <CalendarIcon className="text-muted-foreground" />
          {value ? formatDate(value) : 'Pick a date'}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-0" align="start">
        <Calendar
          mode="single"
          autoFocus
          selected={selected}
          defaultMonth={selected ?? first}
          // The report covers November up to today, nothing else
          startMonth={first}
          endMonth={toDate(period.to)}
          disabled={[{ before: first }, { after: last }]}
          today={last}
          onSelect={(date) => {
            if (!date) return
            onChange(toIso(date))
            setOpen(false)
            onClose()
          }}
        />
      </PopoverContent>
    </Popover>
  )
}

export function CategoryField({
  value,
  label,
  control,
  onChange,
  onClose,
}: {
  value: string
  label: string
  control: ControlProps
  onChange: (category: string) => void
  onClose: () => void
}) {
  return (
    <Select
      value={value}
      onValueChange={onChange}
      // Blur fires when the list opens, so touch the field when it closes
      onOpenChange={(open) => !open && onClose()}
      disabled={control.disabled}
    >
      <SelectTrigger {...control} size="sm" aria-label={label} className="w-32">
        <SelectValue placeholder="Choose…" />
      </SelectTrigger>
      <SelectContent>
        {categories.map((c) => (
          <SelectItem key={c} value={c}>
            {c}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  )
}

import type { KeyboardEvent, ReactNode } from 'react'
import { TriangleAlert, X } from 'lucide-react'
import type { ColumnDef, Table } from '@tanstack/react-table'

import { Button } from '#/components/ui/button'
import { Input } from '#/components/ui/input'
import type { Expense } from './data'
import { formatDate, money, parseAmount } from './drafts'
import type { Draft, Errors, Field } from './drafts'
import { CategoryField, DateField } from './pickers'

/** Saved expenses and draft rows share one table */
export type Row =
  | { kind: 'saved'; id: string; expense: Expense }
  | { kind: 'draft'; id: string; draft: Draft; number: number }

export interface DraftMeta {
  /** Errors to show: only for fields left once, or all after a save attempt */
  shownErrors: (id: string) => Errors
  duplicates: Set<string>
  saving: boolean
  update: (id: string, field: Field, value: string) => void
  touch: (id: string, field: Field) => void
  remove: (id: string) => void
  /** Enter in a text field: go to the same field one row down */
  next: (id: string, field: Field) => void
}

const getMeta = (table: Table<Row>) =>
  table.options.meta as unknown as DraftMeta

const errorId = (id: string, field: Field) => `${id}-${field}-error`

/** An input with its error message under it */
function Cell({
  row,
  field,
  meta,
  children,
}: {
  row: Extract<Row, { kind: 'draft' }>
  field: Field
  meta: DraftMeta
  children: (props: {
    'data-draft': string
    'data-field': Field
    'aria-invalid': boolean
    'aria-describedby': string | undefined
    disabled: boolean
    onBlur: () => void
    onKeyDown: (event: KeyboardEvent<HTMLElement>) => void
  }) => ReactNode
}) {
  const error = meta.shownErrors(row.id)[field]
  return (
    <div className="space-y-1">
      {children({
        'data-draft': row.id,
        'data-field': field,
        'aria-invalid': !!error,
        'aria-describedby': error ? errorId(row.id, field) : undefined,
        disabled: meta.saving,
        onBlur: () => meta.touch(row.id, field),
        onKeyDown: (event) => {
          if (event.key !== 'Enter' || event.nativeEvent.isComposing) return
          event.preventDefault()
          meta.next(row.id, field)
        },
      })}
      {error ? (
        <p id={errorId(row.id, field)} className="text-xs text-destructive">
          {error}
        </p>
      ) : null}
    </div>
  )
}

const label = (row: Extract<Row, { kind: 'draft' }>, what: string) =>
  `${what}, new row ${row.number}`

export const columns: ColumnDef<Row>[] = [
  {
    id: 'date',
    header: 'Date',
    cell: ({ row: { original: row }, table }) =>
      row.kind === 'saved' ? (
        <span className="tabular-nums">{formatDate(row.expense.date)}</span>
      ) : (
        <Cell row={row} field="date" meta={getMeta(table)}>
          {({ onBlur, onKeyDown: _, ...control }) => (
            <DateField
              value={row.draft.date}
              label={label(row, 'Date')}
              control={control}
              onChange={(iso) => getMeta(table).update(row.id, 'date', iso)}
              onClose={onBlur}
            />
          )}
        </Cell>
      ),
  },
  {
    id: 'description',
    header: 'Description',
    cell: ({ row: { original: row }, table }) =>
      row.kind === 'saved' ? (
        row.expense.description
      ) : (
        <Cell row={row} field="description" meta={getMeta(table)}>
          {(props) => (
            <Input
              {...props}
              aria-label={label(row, 'Description')}
              placeholder="What was it for?"
              value={row.draft.description}
              onChange={(e) =>
                getMeta(table).update(row.id, 'description', e.target.value)
              }
              className="h-8 min-w-44 px-2"
            />
          )}
        </Cell>
      ),
  },
  {
    id: 'category',
    header: 'Category',
    cell: ({ row: { original: row }, table }) =>
      row.kind === 'saved' ? (
        row.expense.category
      ) : (
        <Cell row={row} field="category" meta={getMeta(table)}>
          {({ onBlur, onKeyDown: _, ...control }) => (
            <CategoryField
              value={row.draft.category}
              label={label(row, 'Category')}
              control={control}
              onChange={(value) =>
                getMeta(table).update(row.id, 'category', value)
              }
              onClose={onBlur}
            />
          )}
        </Cell>
      ),
  },
  {
    id: 'amount',
    header: () => <span className="block text-right">Amount</span>,
    cell: ({ row: { original: row }, table }) => {
      if (row.kind === 'saved') {
        return (
          <span className="block text-right tabular-nums">
            {money(row.expense.amount)}
          </span>
        )
      }
      const meta = getMeta(table)
      return (
        <Cell row={row} field="amount" meta={meta}>
          {(props) => (
            <Input
              {...props}
              inputMode="decimal"
              aria-label={label(row, 'Amount in dollars')}
              placeholder="0.00"
              value={row.draft.amount}
              onChange={(e) => meta.update(row.id, 'amount', e.target.value)}
              onBlur={() => {
                // Tidy "12.5" into "12.50" once the user moves on
                const n = parseAmount(row.draft.amount)
                if (Number.isFinite(n) && !/\.\d{3,}$/.test(row.draft.amount))
                  meta.update(row.id, 'amount', n.toFixed(2))
                props.onBlur()
              }}
              className="ml-auto h-8 w-28 px-2 text-right tabular-nums"
            />
          )}
        </Cell>
      )
    },
  },
  {
    id: 'actions',
    header: () => <span className="sr-only">Actions</span>,
    cell: ({ row: { original: row }, table }) => {
      if (row.kind === 'saved') return null
      const meta = getMeta(table)
      return (
        <div className="flex items-center justify-end gap-1">
          {meta.duplicates.has(row.id) ? (
            <span
              title="Same date, amount and description as another expense"
              className="flex items-center gap-1 text-xs whitespace-nowrap text-amber-700 dark:text-amber-400"
            >
              <TriangleAlert aria-hidden className="size-3.5" />
              Duplicate?
            </span>
          ) : null}
          <Button
            variant="ghost"
            size="icon"
            className="size-8"
            disabled={meta.saving}
            aria-label={`Remove new row ${row.number}`}
            onClick={() => meta.remove(row.id)}
          >
            <X />
          </Button>
        </div>
      )
    },
  },
]

import type { ReactNode } from 'react'
import {
  flexRender,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableFooter,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { cn } from '#/lib/utils'
import { columns } from './columns'
import type { DraftMeta, Row } from './columns'

export function DraftRowsTable({
  rows,
  meta,
  fresh,
  footer,
}: {
  rows: Row[]
  meta: DraftMeta
  /** Ids of rows that were just saved, highlighted for a moment */
  fresh: Set<string>
  /** The "Add row" line under the last row */
  footer: ReactNode
}) {
  const table = useReactTable({
    data: rows,
    columns,
    // Stable ids keep each input, and the focus in it, across keystrokes
    getRowId: (row) => row.id,
    getCoreRowModel: getCoreRowModel(),
    meta,
  })

  return (
    <div className="overflow-hidden rounded-md border">
      <Table className="min-w-[640px]">
        <TableHeader>
          {table.getHeaderGroups().map((group) => (
            <TableRow key={group.id} className="hover:bg-transparent">
              {group.headers.map((header) => (
                <TableHead
                  key={header.id}
                  className={cn(
                    header.column.id === 'amount' && 'w-32',
                    header.column.id === 'actions' && 'w-32',
                  )}
                >
                  {flexRender(
                    header.column.columnDef.header,
                    header.getContext(),
                  )}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {table.getRowModel().rows.map((row) => {
            const draft = row.original.kind === 'draft'
            return (
              <TableRow
                key={row.id}
                data-kind={row.original.kind}
                className={cn(
                  'transition-colors duration-1000',
                  draft &&
                    'bg-blue-50/60 hover:bg-blue-50/60 dark:bg-blue-500/5 dark:hover:bg-blue-500/5',
                  fresh.has(row.id) && 'bg-emerald-50 dark:bg-emerald-500/10',
                )}
              >
                {row.getVisibleCells().map((cell, i) => (
                  <TableCell
                    key={cell.id}
                    className={cn(
                      draft ? 'py-1.5 align-top' : 'h-11',
                      // A blue edge marks the rows that aren't saved yet
                      draft &&
                        i === 0 &&
                        'shadow-[inset_3px_0_0_var(--color-blue-500)]',
                    )}
                  >
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </TableCell>
                ))}
              </TableRow>
            )
          })}
        </TableBody>
        <TableFooter className="bg-transparent">
          <TableRow className="hover:bg-transparent">
            <TableCell colSpan={columns.length} className="p-1.5">
              {footer}
            </TableCell>
          </TableRow>
        </TableFooter>
      </Table>
    </div>
  )
}

import { useEffect, useMemo, useRef, useState } from 'react'
import { LoaderCircle, Plus, TriangleAlert } from 'lucide-react'

import { Button } from '#/components/ui/button'
import { cn } from '#/lib/utils'
import { periodLabel, saved as initialSaved } from './data'
import type { Expense } from './data'
import type { DraftMeta, Row } from './columns'
import { DraftRowsTable } from './data-table'
import {
  batch,
  duplicates,
  emptyDraft,
  fields,
  isBlank,
  money,
  toExpense,
  validate,
} from './drafts'
import type { Draft, Errors, Field } from './drafts'

// One row ready to save, one missing its amount, one that repeats a saved
// expense, so every state is on screen from the start
const initialDrafts: Draft[] = [
  {
    id: 'draft-1',
    date: '2026-11-12',
    description: 'Taxi to airport',
    category: 'Travel',
    amount: '42.80',
  },
  {
    id: 'draft-2',
    date: '2026-11-12',
    description: 'Team lunch',
    category: 'Meals',
    amount: '',
  },
  {
    id: 'draft-3',
    date: '2026-11-04',
    description: 'Client dinner',
    category: 'Meals',
    amount: '148.50',
  },
]

const SAVE_DELAY = 700

export function DraftRowsDemo() {
  const [saved, setSaved] = useState<Expense[]>(initialSaved)
  const [drafts, setDrafts] = useState<Draft[]>(initialDrafts)
  // `${id}:${field}` for every field the user has left at least once
  const [touched, setTouched] = useState<Set<string>>(new Set())
  // After a failed save, every error shows, touched or not
  const [attempted, setAttempted] = useState(false)
  const [saving, setSaving] = useState(false)
  const [fresh, setFresh] = useState<Set<string>>(new Set())
  const [confirmDiscard, setConfirmDiscard] = useState(false)
  const [message, setMessage] = useState('')

  const nextId = useRef(4)
  const root = useRef<HTMLDivElement>(null)
  // Focus to move once the rows it points at have rendered
  const focusTarget = useRef<{ id: string; field: Field } | null>(null)

  useEffect(() => {
    const target = focusTarget.current
    if (!target) return
    focusTarget.current = null
    root.current
      ?.querySelector<HTMLElement>(
        `[data-draft="${target.id}"][data-field="${target.field}"]`,
      )
      ?.focus()
  })

  useEffect(() => {
    if (!confirmDiscard) return
    const timer = setTimeout(() => setConfirmDiscard(false), 3000)
    return () => clearTimeout(timer)
  }, [confirmDiscard])

  const summary = batch(drafts)
  const dupes = useMemo(() => duplicates(drafts, saved), [drafts, saved])

  function addRow(field: Field = 'description') {
    const draft = emptyDraft(`draft-${nextId.current++}`, drafts.at(-1))
    setDrafts([...drafts, draft])
    focusTarget.current = { id: draft.id, field }
  }

  function shownErrors(id: string): Errors {
    const draft = drafts.find((d) => d.id === id)
    // Blank rows are skipped on save, so they never complain
    if (!draft || isBlank(draft)) return {}
    const errors = validate(draft)
    return Object.fromEntries(
      Object.entries(errors).filter(
        ([field]) =>
          (attempted && !isBlank(draft)) || touched.has(`${id}:${field}`),
      ),
    )
  }

  function save() {
    if (!summary.filled.length) {
      setMessage('Nothing to save yet. Fill in a row first.')
      return
    }
    if (summary.invalid.length) {
      setAttempted(true)
      const first = summary.invalid[0]
      const errors = validate(first)
      focusTarget.current = {
        id: first.id,
        field: fields.find((f) => errors[f])!,
      }
      const n = summary.invalid.length
      setMessage(`Fix ${n} ${n === 1 ? 'row' : 'rows'} before saving.`)
      return
    }
    setSaving(true)
    setMessage('Saving…')
    // Stands in for the request that saves the whole batch at once
    setTimeout(() => {
      const added = summary.filled.map((d) =>
        toExpense(d, `exp-${nextId.current++}`),
      )
      setSaved((s) =>
        [...s, ...added].sort((a, b) => a.date.localeCompare(b.date)),
      )
      setDrafts([])
      setTouched(new Set())
      setAttempted(false)
      setSaving(false)
      setFresh(new Set(added.map((e) => e.id)))
      setTimeout(() => setFresh(new Set()), 1600)
      const n = added.length
      setMessage(`Saved ${n} ${n === 1 ? 'expense' : 'expenses'}.`)
    }, SAVE_DELAY)
  }

  function discard() {
    // Typed-in rows take two clicks to throw away; blank ones go at once
    if (summary.filled.length && !confirmDiscard) {
      setConfirmDiscard(true)
      return
    }
    setDrafts([])
    setTouched(new Set())
    setAttempted(false)
    setConfirmDiscard(false)
    setMessage('Draft rows discarded.')
  }

  const meta: DraftMeta = {
    shownErrors,
    duplicates: dupes,
    saving,
    update: (id, field, value) => {
      setDrafts((all) =>
        all.map((d) => (d.id === id ? { ...d, [field]: value } : d)),
      )
      setConfirmDiscard(false)
    },
    touch: (id, field) =>
      setTouched((t) =>
        t.has(`${id}:${field}`) ? t : new Set(t).add(`${id}:${field}`),
      ),
    remove: (id) => {
      const i = drafts.findIndex((d) => d.id === id)
      const rest = drafts.filter((d) => d.id !== id)
      setDrafts(rest)
      // Keep focus in the table: on the row that moved up, or the one above
      const neighbour = rest.at(i) ?? rest.at(i - 1)
      if (neighbour)
        focusTarget.current = { id: neighbour.id, field: 'description' }
      else root.current?.querySelector<HTMLElement>('[data-add-row]')?.focus()
    },
    next: (id, field) => {
      const i = drafts.findIndex((d) => d.id === id)
      if (i === drafts.length - 1) addRow(field)
      else focusTarget.current = { id: drafts[i + 1].id, field }
      // Leaving a field with Enter counts as leaving it; the re-render
      // also lets the effect move focus
      setTouched((t) => new Set(t).add(`${id}:${field}`))
    },
  }

  const rows: Row[] = [
    ...saved.map((expense) => ({
      kind: 'saved' as const,
      id: expense.id,
      expense,
    })),
    ...drafts.map((draft, i) => ({
      kind: 'draft' as const,
      id: draft.id,
      draft,
      number: i + 1,
    })),
  ]

  const savedTotal = saved.reduce((sum, e) => sum + e.amount, 0)
  const invalid = summary.invalid.length

  return (
    <div ref={root} className="space-y-3">
      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <p className="text-sm">
          <span className="font-medium">Expense report</span>{' '}
          <span className="text-muted-foreground">{periodLabel}</span>
        </p>
        <p className="text-sm text-muted-foreground tabular-nums">
          {saved.length} saved ·{' '}
          <span className="font-medium text-foreground">
            {money(savedTotal)}
          </span>
        </p>
      </div>

      <DraftRowsTable
        rows={rows}
        meta={meta}
        fresh={fresh}
        footer={
          <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
            <Button
              data-add-row
              variant="ghost"
              size="sm"
              disabled={saving}
              onClick={() => addRow()}
            >
              <Plus /> Add row
            </Button>
            <span className="text-xs text-muted-foreground">
              Enter in a description or amount moves down a row, and adds one at
              the end.
            </span>
          </div>
        }
      />

      <div
        className={cn(
          'flex flex-wrap items-center justify-between gap-3 rounded-md border px-3 py-2',
          !drafts.length && 'border-dashed',
        )}
      >
        <div className="min-w-0 text-sm">
          {drafts.length ? (
            <p className="flex flex-wrap items-center gap-x-2 gap-y-1">
              <span className="font-medium">
                {summary.filled.length} new{' '}
                {summary.filled.length === 1 ? 'row' : 'rows'}
              </span>
              <span className="text-muted-foreground tabular-nums">
                {money(summary.total)}
              </span>
              {invalid ? (
                <span className="text-destructive">
                  · {invalid} {invalid === 1 ? 'needs' : 'need'} fixing
                </span>
              ) : null}
              {dupes.size ? (
                <span className="flex items-center gap-1 text-amber-700 dark:text-amber-400">
                  <TriangleAlert aria-hidden className="size-3.5" />
                  {dupes.size} possible{' '}
                  {dupes.size === 1 ? 'duplicate' : 'duplicates'}
                </span>
              ) : null}
            </p>
          ) : (
            <p className="text-muted-foreground">
              No unsaved rows. Add some to start a batch.
            </p>
          )}
          <p
            aria-live="polite"
            className="text-xs text-muted-foreground empty:hidden"
          >
            {message}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant={confirmDiscard ? 'destructive' : 'outline'}
            size="sm"
            disabled={!drafts.length || saving}
            onClick={discard}
          >
            {confirmDiscard
              ? `Discard ${summary.filled.length} ${summary.filled.length === 1 ? 'row' : 'rows'}?`
              : 'Discard'}
          </Button>
          <Button size="sm" disabled={!drafts.length || saving} onClick={save}>
            {saving ? (
              <LoaderCircle className="motion-safe:animate-spin" />
            ) : null}
            {saving
              ? 'Saving…'
              : summary.filled.length
                ? `Save ${summary.filled.length} ${summary.filled.length === 1 ? 'row' : 'rows'}`
                : 'Save'}
          </Button>
        </div>
      </div>
    </div>
  )
}
